use std::io::{self,BufRead};
use serde_json::{json,Value};
use yrs::{Any,Doc,Transact,Map,In,MapPrelim,ArrayPrelim,JsonPath,JsonPathEval};
use yrs::types::ToJson;
fn shared(v:Value)->In {match v {Value::Array(a)=>In::Array(ArrayPrelim::from_iter(a.into_iter().map(shared))),Value::Object(m)=>In::Map(MapPrelim::from_iter(m.into_iter().map(|(k,v)|(k,shared(v))))),v=>In::Any(serde_json::from_value(v).unwrap())}}
fn main(){for line in io::stdin().lock().lines(){let input:Value=serde_json::from_str(&line.unwrap()).unwrap();let value:Any=serde_json::from_value(input["value"].clone()).unwrap();let doc=Doc::with_client_id(1);let root=doc.get_or_insert_map("root");for (key,value) in input["value"].as_object().unwrap(){root.insert(&mut doc.transact_mut(),key.as_str(),shared(value.clone()));}let mut results=Vec::new();for path in input["paths"].as_array().unwrap(){let path=path.as_str().unwrap();match JsonPath::parse(path){Err(_)=>results.push(json!({"error":true})),Ok(parsed)=>{let any=value.json_path(&parsed).map(|v|serde_json::to_value(v).unwrap()).collect::<Vec<_>>();let document_path=if path.is_empty(){"".to_string()}else{format!("$.root{}",path.strip_prefix('$').unwrap_or(path))};let document_path=JsonPath::parse(&document_path).unwrap();let txn=doc.transact();let values=txn.json_path(&document_path).map(|v|v.to_json(&txn)).collect::<Vec<_>>();results.push(json!({"any":any,"doc":values}));}}}println!("{}",json!(results));}}
